code_example:
std::vector<int> data = {1, 5, 9};

// Read-only access using constant reference
for (const auto& x : data) {
    // x references the element
}

// Access requiring modification
for (auto& x : data) {
    x *= 2; // Modifies the container element
}

std::map<int, double> lookup = {{10, 3.14}};

// Range iteration with C++17 Structured Binding
// Abstracts the std::pair returned by the iterator
for (const auto& [key, val] : lookup) {
    // Access key and val directly
}

// C++17 requirement for efficiency
for (auto&& x : data) {
    // Use universal reference
}
